 babhruvahana: { av: "🛡️", en: "Babhruvāhana", te: "బభ్రువాహనుడు", d: "Son of Arjuna and Citrāṅgadā, who became king of Maṇipūra.", dt: "అర్జున చిత్రాంగదల కుమారుడు, మణిపుర రాజు." },
 subhadra: { av: "💐", en: "Subhadrā", te: "సుభద్ర", d: "Sister of Kṛṣṇa and Balarāma, wife of Arjuna and mother of Abhimanyu.", dt: "కృష్ణ బలరాముల చెల్లెలు, అర్జునుని భార్య, అభిమన్యుని తల్లి." },
 abhimanyu: { av: "🌟", en: "Abhimanyu", te: "అభిమన్యుడు", d: "Son of Arjuna and Subhadrā, a brave young warrior.", dt: "అర్జున సుభద్రల కుమారుడు, వీరుడైన యువయోధుడు." },
 maya: { av: "🏛️", en: "Maya", te: "మయుడు", d: "The architect of the asuras, saved by Arjuna from the Khāṇḍava fire. He built the wondrous hall of the Pāṇḍavas.", dt: "అసురుల శిల్పి; ఖాండవ దహనంలో అర్జునుడు రక్షించాడు. పాండవుల అద్భుత సభను నిర్మించాడు." }
