   "గరుత్మంతుడు ఎంతో బలవంతుడైనా దేవతలు భయపడినప్పుడు తనను తాను చిన్నగా చేసుకున్నాడు, చిన్నారి మునుల కోసం బరువైన కొమ్మను మోశాడు. బలాన్ని మంచిగా ఎలా వాడాలో ఇది ఏమి చెబుతోంది?"
