     "🐍",
     "In Indian tradition, the snake sacrifice is remembered every year at Nāga Pañcamī, when people offer milk to serpents and pray for their family's safety. Many also recite the name of Āstīka for protection from snakes.",
     "భారతీయ సంప్రదాయంలో ప్రతి సంవత్సరం నాగపంచమి నాడు నాగులకు పాలు పోసి కుటుంబ క్షేమం కోసం ప్రార్థిస్తారు. పాముల నుండి రక్షణ కోసం చాలామంది ఆస్తీకుని పేరు కూడా జపిస్తారు."
