     "మరి అవతలి పక్షం? {duryodhana|దుర్యోధనుడు} కలి అంశతో పుట్టాడు — కలహయుగపు స్వరూపం. అతని మేనమామ {shakuni|శకుని} దానికి ముందు యుగమైన ద్వాపరుడు. దుర్యోధనుని సోదరులు పులస్త్య వంశపు రాక్షసులు. శిశుపాలుడు మళ్ళీ పుట్టిన హిరణ్యకశిపుడు; జరాసంధుడు విప్రచిత్తి అనే అసురుడు; కంసుడు కాలనేమి. ధృతరాష్ట్రుడు హంసుడనే గంధర్వరాజు."
