     "ధృష్టద్యుమ్నుడు అగ్ని అంశ; అభిమన్యుడు చంద్రుని కుమారుడైన వర్చస్సు — పదహారేళ్ళకు మాత్రమే వస్తానన్నాడు; ద్రౌపది ఐదుగురు కుమారులు విశ్వేదేవతలు. ద్రుపదుడు, విరాటుడు వంటి రాజులు మరుత్తుల నుండి వచ్చారు. కాబట్టి జనమేజయా — మహాయుద్ధం గురించి విన్నప్పుడు, స్వర్గమే భూమికి దిగివచ్చిందని గుర్తుంచుకో."
