     "కథ అర్థం కావడానికే ఈ జాబితా ముందుగా చెప్పబడింది. అయినా మహాభారతం ఎవరినీ కేవలం నాయకుడిగానో ప్రతినాయకుడిగానో చూపదు — దుర్యోధనుడు ధైర్యవంతుడు, స్నేహితులకు నమ్మకస్తుడు; కర్ణుడు అపరిమిత దాత; పాండవులు కూడా పెద్ద తప్పులు చేస్తారు. మనుషులుగా పుట్టిన దేవతలు కూడా మనలాగే ఎంచుకోవలసిందే."
