     "p",
     "He embraced his son, honoured Śakuntalā as his chief queen, and asked her forgiveness for his harsh words. {bharata|Bharata} grew up to be a world-conqueror who performed many great sacrifices. From him comes the name of the Bhārata family — the Bhāratas — and of our land, Bhārata.",
     "కుమారుని ఆలింగనం చేసుకుని, శకుంతలను పట్టమహిషిగా గౌరవించి, తన కఠిన మాటలకు క్షమాపణ అడిగాడు. {bharata|భరతుడు} పెరిగి ఎన్నో మహాయజ్ఞాలు చేసిన సార్వభౌముడయ్యాడు. అతని నుండే భరతవంశానికి — భారతులకు — మన దేశానికి — భారతం అనే పేరు వచ్చింది."
