     "మహాభారతంలో దుష్యంతుడు గుర్తు లేనట్లు నటిస్తాడు. తరువాత మహాకవి కాళిదాసు తన *అభిజ్ఞాన శాకుంతలం* నాటకంలో దుర్వాసుని శాపం, పోయిన ఉంగరం కలిపి కథను తిరిగి చెప్పాడు — అక్కడ రాజు నిజంగానే మరచిపోతాడు."
