     "ఈ వరం — *ఇచ్ఛామృత్యువు*, తన ఇష్టంతోనే మరణం — వల్లే ఎన్నో ఏళ్ళ తరువాత భీష్ముడు యాభై ఎనిమిది రాత్రులు అంపశయ్యపై ఉండి, సూర్యుడు ఉత్తరాయణంలోకి వచ్చినప్పుడే దేహం విడిచిపెట్టాడు."
