     "dyk",
     "👶",
     "Through Aṇī-Māṇḍavya's curse, the Mahābhārata gives one of the world's oldest rules that young children should not be punished as if they were grown-ups.",
     "అణిమాండవ్యుని శాపం ద్వారా, చిన్నపిల్లలను పెద్దవారిలా శిక్షించకూడదనే ప్రపంచంలోని అత్యంత పురాతన నియమాలలో ఒకదాన్ని మహాభారతం చెబుతుంది."
