    [
     "dyk",
     "🎗️",
     "Some say Gāndhārī's blindfold was the greatest act of devotion; others wonder whether a seeing wife could have helped her blind husband more. The Mahābhārata leaves us to think about it. Her tapas made her so powerful that later her glance alone could burn.",
     "గాంధారి గంతలు మహోన్నతమైన పతిభక్తి అని కొందరంటారు; చూపున్న భార్య అంధుడైన భర్తకు ఇంకా ఎక్కువ సహాయం చేయగలిగేదేమో అని మరికొందరు ఆలోచిస్తారు. మహాభారతం దీన్ని మనకే వదిలేస్తుంది. ఆమె తపశ్శక్తి ఎంతంటే తరువాత ఆమె చూపే దహించగలిగింది."
    ]
