     "గాంధారి ఆ దీర్ఘకాలం గర్భవతిగా ఉన్నప్పుడు ఒక వైశ్య దాసి ధృతరాష్ట్రుని సేవించింది; ఆమెకూ ఒక కుమారుడు పుట్టాడు — జ్ఞాని, మంచివాడు — {yuyutsu|యుయుత్సుడు}. అలా ధృతరాష్ట్రునికి నూట ఒక్క కుమారులు, ఒక కుమార్తె."
