     "p",
     "Mādrī remembered the curse and tried with all her strength to stop him. But fate had come for Pāṇḍu. He took her in his arms — and, just as the sage Kindama had said, he died in that very moment.",
     "మాద్రికి శాపం గుర్తొచ్చింది; సర్వశక్తితో అతన్ని ఆపడానికి ప్రయత్నించింది. కానీ పాండురాజుకు విధి వచ్చేసింది. ఆమెను కౌగిలించుకున్నాడు — కిందముడు చెప్పినట్లే ఆ క్షణమే మరణించాడు."
