     "But Mādrī said: ‘No, sister. He died desiring me — I must go with him. And I could never love your sons as my own, the way you will love mine. Take care of Nakula and Sahadeva, and raise them as your own.’ So Mādrī gave her sons into Kuntī's arms and followed her husband on the funeral pyre.",
