   "కర్ణుని నైపుణ్యాన్ని కాకుండా అతని వంశాన్ని చూసి తీర్పు చెప్పారు. దుర్యోధనుడు అతనికి అండగా నిలిచాడు — కానీ అతనికీ సొంత కారణాలు ఉన్నాయి. ఒకే ఎంపికలో దయ, స్వార్థం రెండూ ఉండగలవా?"
