   "పాండవులకు హాని చేయడానికి పంపబడిన హిడింబి బదులుగా వారిని కాపాడాలని ఎంచుకుంది. తప్పని తెలిసినప్పుడు సొంత కుటుంబం కోరుకునేదానికి వ్యతిరేకంగా నిలబడటానికి ఏమి కావాలి?"
