   [
    [
     "p",
     "Next morning {bhima|Bhīma} set off with the cart of food. When he reached Baka's forest, he sat down and began to eat it himself, calling out the demon's name between mouthfuls. Baka came storming out, red-eyed and enormous. ‘Who is this fool eating my food in front of me?’ He struck Bhīma on the back with both fists. Bhīma did not even turn around; he just kept eating.",
     "మరుసటి ఉదయం {bhima|భీముడు} అన్నపు బండితో బయలుదేరాడు. బకుని అడవి చేరగానే కూర్చుని ఆ అన్నాన్ని తానే తినడం మొదలుపెట్టాడు — ముద్దల మధ్య రాక్షసుని పేరు పిలుస్తూ. ఎర్రని కళ్ళతో, మహాకాయంతో బకుడు దూసుకువచ్చాడు. ‘నా ముందే నా అన్నం తింటున్న ఈ మూర్ఖుడెవడు?’ రెండు పిడికిళ్ళతో భీముని వీపుపై కొట్టాడు. భీముడు వెనక్కి తిరగను కూడా తిరగలేదు; తింటూనే ఉన్నాడు."
    ],
    [
     "p",
     "When the last grain was gone, Bhīma washed his hands and stood up. Baka tore up a tree and hurled it; Bhīma caught it and threw it back. They fought with trees until the forest was bare. Then Bhīma threw Baka down, put his knee on his back, and broke him in two like a stick. The demon died with a terrible scream. Bhīma dragged the body to the town gate, left it there, and walked quietly home.",
     "చివరి మెతుకు అయిపోయాక భీముడు చేతులు కడుక్కుని లేచాడు. బకుడు ఒక చెట్టును పెకలించి విసిరాడు; భీముడు దాన్ని పట్టుకుని తిరిగి విసిరాడు. అడవి బోడిగా అయ్యేవరకు చెట్లతో పోరాడారు. తరువాత భీముడు బకుని కింద పడేసి, వీపుపై మోకాలు ఉంచి, కర్రను విరిచినట్లు రెండుగా విరిచాడు. భయంకరమైన కేకతో రాక్షసుడు మరణించాడు. భీముడు శవాన్ని ఊరి ద్వారం దగ్గరకు ఈడ్చుకువచ్చి అక్కడ వదిలి, నిశ్శబ్దంగా ఇంటికి నడిచాడు."
    ],
    [
     "p",
     "In the morning the townspeople found Baka's body and were amazed and overjoyed. ‘Whose turn was it yesterday?’ they asked, and went to the brahmin. Keeping the secret, he said only, ‘A great brahmin with mantras saved us.’ And the whole town held a festival for the gods.",
     "ఉదయం ఊరివారు బకుని శవాన్ని చూసి ఆశ్చర్యంతో, ఆనందంతో పొంగిపోయారు. ‘నిన్న ఎవరి వంతు?’ అని అడిగి బ్రాహ్మణుని దగ్గరకు వెళ్ళారు. రహస్యాన్ని కాపాడుతూ అతను, ‘మంత్రాలు తెలిసిన ఒక మహానుభావుడైన బ్రాహ్మణుడు మమ్మల్ని కాపాడాడు’ అని మాత్రమే అన్నాడు. ఊరంతా దేవతలకు ఉత్సవం చేసింది."
    ]
   ]
