  "think": [
   "Arjuna went into waters that everyone else was afraid of, and freed the cursed apsarās. Is there something others avoid that you could bravely help with?",
   "అందరూ భయపడే నీటిలోకి అర్జునుడు దిగి శాపగ్రస్త అప్సరసలను విడిపించాడు. ఇతరులు తప్పించుకునే ఏదైనా విషయంలో మీరు ధైర్యంగా సహాయం చేయగలరా?"
  ]
