    "Arjuna fell in love with Subhadrā, Kṛṣṇa's sister, and carried her off with Kṛṣṇa's blessing.",
    "అర్జునుడు కృష్ణుని చెల్లెలు సుభద్రను ప్రేమించి, కృష్ణుని ఆశీస్సులతో ఆమెను తీసుకెళ్ళాడు."
